/* Palette: deep navy (#0f172a), slate (#1e293b), teal (#14b8a6), light gray (#e2e8f0), white (#f8fafc) */
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: #0f172a;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
  color: #f8fafc;
}

.card {
  background: #1e293b;
  border-radius: 1.5rem;
  padding: 2rem 1.5rem;
  width: 100%;
  max-width: 400px;
  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.5);
  border: 1px solid #334155;
}

h1 {
  font-size: 1.5rem;
  font-weight: 600;
  text-align: center;
  margin-bottom: 1.5rem;
  color: #e2e8f0;
  letter-spacing: 0.02em;
}

.display {
  background: #0f172a;
  border-radius: 1rem;
  padding: 1.5rem 1rem;
  text-align: center;
  margin-bottom: 2rem;
  border: 2px solid #334155;
}

.time {
  font-size: 3.5rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  color: #14b8a6;
  line-height: 1.2;
}

.price {
  font-size: 1.5rem;
  font-weight: 500;
  color: #e2e8f0;
  margin-top: 0.5rem;
}

.buttons {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.btn {
  background: #14b8a6;
  color: #0f172a;
  border: none;
  border-radius: 0.75rem;
  padding: 0.875rem 1rem;
  font-size: 1.125rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
  font-family: inherit;
  min-height: 3rem;
}

.btn:hover {
  background: #2dd4bf;
}

.btn:focus-visible {
  outline: 3px solid #f8fafc;
  outline-offset: 2px;
}

.btn:active {
  transform: scale(0.97);
}

.btn.clear {
  background: #64748b;
  color: #f8fafc;
}

.btn.clear:hover {
  background: #94a3b8;
}

.max-note {
  margin-top: 1rem;
  text-align: center;
  color: #f87171;
  font-size: 0.95rem;
  font-weight: 500;
}

[hidden] {
  display: none !important;
}

@media (min-width: 480px) {
  .card {
    padding: 2.5rem 2rem;
  }
  .time {
    font-size: 4rem;
  }
}

const timeDisplay = document.getElementById('timeDisplay');
const priceDisplay = document.getElementById('priceDisplay');
const add15 = document.getElementById('add15');
const add60 = document.getElementById('add60');
const clearBtn = document.getElementById('clear');
const maxNote = document.getElementById('maxNote');

const MAX_MINUTES = 180;
const RATE_PER_HOUR = 2.00;

let totalMinutes = 0;

function updateDisplay() {
  const hours = Math.floor(totalMinutes / 60);
  const minutes = totalMinutes % 60;
  timeDisplay.textContent = `${hours}:${minutes.toString().padStart(2, '0')}`;
  const price = (totalMinutes / 60) * RATE_PER_HOUR;
  priceDisplay.textContent = `$${price.toFixed(2)}`;
  maxNote.hidden = totalMinutes < MAX_MINUTES;
}

function addMinutes(minutes) {
  totalMinutes = Math.min(totalMinutes + minutes, MAX_MINUTES);
  updateDisplay();
}

add15.addEventListener('click', () => addMinutes(15));
add60.addEventListener('click', () => addMinutes(60));
clearBtn.addEventListener('click', () => {
  totalMinutes = 0;
  updateDisplay();
});

updateDisplay();
